package cryptosquare

import (
	"math"
	"strings"
	"unicode"
)

// Encode normalizes the plaintext (lower-casing and removing spaces and
// punctuation), arranges it into a rectangle as square as possible, and
// returns the encoded text read down the columns left to right, with one
// chunk per column separated by spaces.
func Encode(pt string) string {
	var normalized strings.Builder
	for _, r := range pt {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			normalized.WriteRune(unicode.ToLower(r))
		}
	}
	msg := normalized.String()
	n := len(msg)
	if n == 0 {
		return ""
	}

	c := int(math.Ceil(math.Sqrt(float64(n))))
	r := (n + c - 1) / c

	chunks := make([]string, c)
	for i := 0; i < c; i++ {
		chunk := make([]byte, r)
		for j := 0; j < r; j++ {
			pos := i*r + j
			if pos < n {
				chunk[j] = msg[pos]
			} else {
				chunk[j] = ' '
			}
		}
		chunks[i] = string(chunk)
	}
	return strings.Join(chunks, " ")
}

